import json

with open('/app/chart_data.json', 'r') as f:
    data = json.load(f)

mlabels = data['mlabels']
mclose = data['mclose']
mvol = data['mvol']
mdd = data['mdd']
mvolat = data['mvolat']
mspread = data['mspread']
annual = data['annual']

# Format volume for display
def fmt_vol(v):
    if v >= 1_000_000:
        return f"{v/1_000_000:.1f}M"
    return f"{v/1_000:.0f}K"

# Build annual rows
annual_rows = ""
for a in annual:
    ret_class = "positive" if a['return'] >= 0 else "negative"
    annual_rows += f"""<tr>
        <td>{a['year']}</td>
        <td class="{ret_class}">{a['return']:+.1f}%</td>
        <td>{a['vol']:.1f}%</td>
        <td>{fmt_vol(a['avg_volume'])}</td>
        <td>${a['high']:.2f}</td>
        <td>${a['low']:.2f}</td>
        <td>${a['close']:.2f}</td>
    </tr>"""

# decade data
decade_data = [
    {"label": "2000–2009", "ret": "+200.0%", "cagr": "11.6%"},
    {"label": "2010–2019", "ret": "+604.4%", "cagr": "21.6%"},
    {"label": "2020–2026", "ret": "−34.4%", "cagr": "−6.7%"},
]

decade_rows = ""
for d in decade_data:
    decade_rows += f"""<tr><td>{d['label']}</td><td>{d['ret']}</td><td>{d['cagr']}</td></tr>"""

# Top volume days
vol_days = [
    {"date": "Jun 28, 2024", "vol": "130.0M", "close": "$72.94", "chg": "−2.3%"},
    {"date": "Jun 27, 2025", "vol": "117.5M", "close": "$71.21", "chg": "+3.2%"},
    {"date": "Dec 19, 2025", "vol": "108.7M", "close": "$58.71", "chg": "−0.8%"},
    {"date": "Feb 27, 2001", "vol": "97.8M", "close": "$3.68", "chg": "−2.5%"},
    {"date": "Jun 29, 2012", "vol": "86.3M", "close": "$18.48", "chg": "−0.1%"},
    {"date": "Sep 19, 2005", "vol": "83.7M", "close": "$8.01", "chg": "−0.2%"},
    {"date": "Jan 30, 2006", "vol": "79.0M", "close": "$7.86", "chg": "−1.0%"},
    {"date": "Mar 18, 2011", "vol": "78.9M", "close": "$16.05", "chg": "−0.5%"},
    {"date": "Mar 21, 2025", "vol": "77.3M", "close": "$66.72", "chg": "+2.0%"},
    {"date": "Jun 26, 2008", "vol": "74.1M", "close": "$11.75", "chg": "−2.2%"},
]
vol_rows = ""
for v in vol_days:
    chg_class = "positive" if v['chg'].startswith('+') else "negative"
    vol_rows += f"""<tr><td>{v['date']}</td><td>{v['vol']}</td><td>{v['close']}</td><td class="{chg_class}">{v['chg']}</td></tr>"""

